"""Two additional original topic packs; no official marks or textbook claims."""
import json,sys,copy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
D=ROOT/'content/question-bank/class-6/english-1st'
template=json.loads((D/'original-skills-001.json').read_text())
def activity(id,kind,instruction,**kw):return dict(id=id,kind=kind,instruction=instruction,marks=None,**kw)
def mcqs(rows):return [dict(id=f'm{i}',question=q,options=dict(zip('ABCD',o)),answer=k,explanation=e) for i,(q,o,k,e) in enumerate(rows,1)]
def short(rows):return [dict(id=f'a{i}',question=q,modelAnswer=a,requiredIdeas=ideas) for i,(q,a,ideas) in enumerate(rows,1)]
def vocab(rows):return [dict(word=w,request=r,acceptedAnswers=a) for w,r,a in rows]
def tf(rows):return [dict(statement=s,answer=a,correction=c) for s,a,c in rows]
def build(number,title,passage,reading,qa,cloze,words,info,truth,summary,matching,sequence,writing):
 p=copy.deepcopy(template);p['id']=f'class6-english1-original-skills-{number:03}';p['passages']=[dict(id='P1',title=title,text=passage,origin='ORIGINAL_UNSEEN')]
 p['activities']=[activity('reading-mcq','reading-mcq','Read P1 and choose the best answer.',passageId='P1',items=mcqs(reading)),activity('reading-answers','reading-short-answer','Answer from P1. Equivalent accurate wording is acceptable.',passageId='P1',items=short(qa)),activity('cloze','contextual-gap','Fill each gap using a word from the box. Use each word once.',passageId='P1',**cloze),activity('vocabulary','vocabulary-in-context','Give the requested meaning in the context of P1.',passageId='P1',items=vocab(words)),activity('information-transfer','information-transfer','Complete the table using P1.',passageId='P1',**info),activity('true-false','true-false','State true or false from P1. Correct each false statement.',passageId='P1',items=tf(truth)),activity('summary','summary','Summarise the main events and lesson of P1 in your own words. No official word limit is asserted.',passageId='P1',modelAnswer=summary,assessment=['Captures the main situation and outcome','Selects key ideas rather than minor details','Does not invent unsupported events','Uses clear connected sentences']),activity('matching','sentence-matching','Match each beginning with one ending. Use each ending once.',**matching),activity('rearranging','sentence-rearranging','Put these sentences in order using the time and reference clues.',**sequence)]
 for id,kind,instruction,model,rubric in writing:
  p['activities'].append(activity(id,kind,instruction,modelAnswer=model,assessment=rubric,note='Original model response. Other relevant, coherent answers are acceptable; no official marks or word limit assigned.'))
 p['coverage']['activityGroups']=len(p['activities']);return p
