def write_or_check(path,text):
 if '--check' in sys.argv:assert path.exists() and path.read_text()==text,str(path)
 else:path.write_text(text)
def render(p,n):
 write_or_check(D/f'original-skills-{n:03}.json',json.dumps(p,ensure_ascii=False,indent=2)+'\n')
 student=[f'# Class 6 English 1st Paper — Original Practice {n:03}','**Draft skill practice, not an official model test. No official marks or duration assigned.**',f"## Passage P1: {p['passages'][0]['title']}",p['passages'][0]['text']]
 teacher=[f'# Practice {n:03} — Answers and assessment guidance','**Teacher review pending. Accept equivalent accurate responses and alternative coherent writing.**']
 for a in p['activities']:
  student += ['## '+a['id'],a['instruction']];teacher+=['## '+a['id']]
  if 'items' in a:
   for i,x in enumerate(a['items'],1):
    student.append(f"{i}. "+x.get('question',x.get('statement',f"{x.get('word','')}: {x.get('request','')}")))
    if 'options' in x:student.append('\n'.join(f'   {k}. {v}' for k,v in x['options'].items()))
    ans=x.get('modelAnswer',x.get('acceptedAnswers',x.get('answer')));teacher.append(f'{i}. '+(str(ans) if not isinstance(ans,list) else '; '.join(ans)))
    for key in ('explanation','correction'):
     if x.get(key):teacher.append(x[key])
  else:
   if a.get('wordBox'):student.append('Word box: '+', '.join(a['wordBox']))
   if a.get('text'):student.append(a['text'])
   if a.get('columns'):student.append('| '+' | '.join(a['columns'])+' |\n|---|---|\n'+'\n'.join('| '+' | '.join(row)+' |' for row in a['rows']))
   for key in ('beginnings','endings','sentences'):
    if key in a:student.append('\n'.join(f'{k}. {v}' for k,v in a[key].items()))
   for key in ('answers','answer','modelAnswer','explanation','assessment','note'):
    if key not in a:continue
    v=a[key]
    if isinstance(v,dict):teacher.append('\n'.join(f'{k}: {val}' for k,val in v.items()))
    elif isinstance(v,list):teacher.append('\n'.join(f"{x['speaker']}: {x['line']}" if isinstance(x,dict) else str(x) for x in v))
    else:teacher.append(v)
 write_or_check(D/f'practice-{n:03}-questions.md','\n\n'.join(student)+'\n')
 write_or_check(D/f'practice-{n:03}-answers.md','\n\n'.join(teacher)+'\n')
for n,p in [(2,p2),(3,p3)]:render(p,n)
print('English original packs 002–003: 24 activity groups, 6 model writing responses; official marks unset.')
